it('review diagnostic logger fault leaves SSO pending', async()=>{
 const config=Constants.expoConfig!;const previous=config.scheme;const previousUrl=process.env.EXPO_PUBLIC_API_URL;
 config.scheme='masarifi-dev';process.env.EXPO_PUBLIC_API_URL='https://api.staging.masarifiratibi.com';
 const diagnosticFailure=new Error('review logger fault');const log=jest.spyOn(console,'info').mockImplementation(()=>{throw diagnosticFailure});
 try{render(<MobileIdentityProvider><StatusProbe /></MobileIdentityProvider>);const bridge=mockRegisterLiveClerkBridge.mock.calls.at(-1)![0] as LiveClerkBridge;
 await act(async()=>{await expect(bridge.signInWithGoogle()).rejects.toBe(diagnosticFailure)});
 log.mockImplementation(()=>undefined);
 await act(async()=>{await expect(bridge.signInWithGoogle()).rejects.toThrow('appShell.auth.unavailable')});
 expect(mockStartSSOFlow).not.toHaveBeenCalled();expect(screen.getByText('sso')).toBeOnTheScreen();
 console.warn('REVIEW_AUTH_FAULT',JSON.stringify({providerCalls:mockStartSSOFlow.mock.calls.length,afterRetry:'sso',failure:'diagnostic exception before finally'}));
 }finally{log.mockRestore();config.scheme=previous;process.env.EXPO_PUBLIC_API_URL=previousUrl;}
});
